// ── NEW FILE: plugins/artibot/hooks/reward-emitter.js (ESM; package is \"type\":\"module\") ──
// Stop/SubagentStop emitter: shapes the hook payload -> reward -> recordReward.
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createRewardMetrics } from '../lib/learning/grpo/reward-metrics.js';
import { computeReward } from '../lib/learning/grpo/reward-capture.js';

const PLUGIN_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

async function readStdin() {
  let raw = '';
  for await (const chunk of process.stdin) raw += chunk;
  try { return raw ? JSON.parse(raw) : {}; } catch { return {}; }
}

// Map the Stop/SubagentStop payload onto reward-capture's EpisodeRewardInput.
// Only fields present are used; absent fields fall through computeReward's guards.
function toEpisode(p) {
  return {
    toolCalls: Array.isArray(p.toolCalls) ? p.toolCalls : [],
    errors: Number(p.errors) || 0,
    testPassRatio: p.testPassRatio,          // undefined => no test signal
    typecheckClean: Boolean(p.typecheckClean),
    userCorrections: Number(p.userCorrections) || 0,
    importanceScore: Number.isFinite(p.importanceScore) ? p.importanceScore : 0.5,
  };
}

async function main() {
  const p = await readStdin();
  if (p.stop_hook_active === true) return;                       // loop guard
  const sessionId = p.session_id || p.sessionId;
  if (!sessionId) return;
  const { reward, rewardComponents } = computeReward(toEpisode(p));
  if (rewardComponents?.invalid || !Number.isFinite(reward)) return;
  const meta = {};
  if (typeof p.effort === 'string') meta.effort = p.effort;     // read by summarizeEpisodes
  if (typeof p.command === 'string') meta.command = p.command;  // read by summarizeEpisodes
  if (Number.isFinite(p.budget)) meta.budget = p.budget;
  if (Number.isFinite(p.tokensUsed)) meta.tokensUsed = p.tokensUsed;
  const metricsPath = path.join(PLUGIN_ROOT, 'runtime', 'reward-metrics.json');
  await createRewardMetrics({ metricsPath }).recordReward(sessionId, reward, rewardComponents, meta);
}

main().catch(() => {}).finally(() => process.exit(0));   // never block teardown

