  // WIRE-11: conflict detection — never silently clobber files owned by
  // another installed extension. Skip same-name (upgrade); honor force.
  const incomingFiles = Array.isArray(manifest.files) ? manifest.files : [];
  if (incomingFiles.length > 0) {
    const installedExts = await listInstalled({ installRoot: options.installRoot });
    const existing = [];
    for (const ext of installedExts) {
      if (ext.name === manifest.name) continue; // upgrade, not a conflict
      const loaded = await loadExtension(ext.path);
      if (loaded.manifest && Array.isArray(loaded.manifest.files)) {
        existing.push({ name: loaded.manifest.name, files: loaded.manifest.files });
      }
    }
    const report = detectConflicts({ name: manifest.name, files: incomingFiles }, existing);
    if (report.hasConflicts && !options.force) {
      const lines = report.conflicts.map((c) => `  ${c.file} (owned by ${c.ownedBy})`).join('\n');
      throw new Error(
        `install conflict: ${report.conflicts.length} file(s) already owned by other extensions:\n${lines}\n(pass force=true to override)`
