// Drains discovered extension manifests into the in-memory registry.
// manifest.hooks entries are { event, handler } where handler is a module path
// (relative to the extension dir) exporting a default fn; manifest.skills entries
// are { name, ...config } objects. Best-effort: malformed entries are skipped.
async function populateRegistryFromExtensions(registry, config) {
  const ext = config?.extensions;
  if (!ext || ext.enabled === false) return;
  if (!Array.isArray(ext.searchPaths) || ext.searchPaths.length === 0) return;
  let discovered = [];
  try { discovered = await discoverExtensions(config); }
  catch (err) { process.stderr.write(`[artibot:extensions] discover failed: ${err?.message || err}\n`); return; }
  for (const d of discovered) {
    if (!d.manifest) continue;
    for (const s of d.skills) {
      try {
        const name = typeof s === 'string' ? s : s?.name;
        const cfg = typeof s === 'string' ? { name, description: name } : s;
        if (name) registry.registerSkill(name, { name, ...cfg });
      } catch (err) { process.stderr.write(`[artibot:extensions:skill] ${err?.message || err}\n`); }
    }
    for (const h of d.hooks) {
      try {
        if (!h?.event || !h?.handler) continue;
